INSERT INTO `app_updates` VALUES (3,'2026.6','OpenCart entegrasyonu eklendi','OpenCart 2.3/3.0/4.x için token korumalı connector ile sipariş, ürün, stok ve fiyat senkronizasyonu; event ile anlık sipariş bildirimi.','feature',1,'2026-06-08 21:57:13',NULL,'2026-06-19 21:57:13','2026-06-19 21:57:13'),(4,'2026.6','WooCommerce entegrasyonu eklendi','WooCommerce REST API v3 ile tam entegrasyon; webhook ile anlık sipariş, stok/fiyat gönderimi.','feature',1,'2026-06-03 21:57:13',NULL,'2026-06-19 21:57:13','2026-06-19 21:57:13'),(5,'2026.5','Shopify entegrasyonu eklendi','Shopify Admin API ile sipariş/ürün/stok/fiyat ve webhook ile anlık sipariş.','feature',1,'2026-06-02 21:57:13',NULL,'2026-06-19 21:57:13','2026-06-19 21:57:13'),(6,'2026.6','Reklam pikselleri & Conversions API','Meta, Google (GA4/Ads) ve TikTok pikselleri + sunucu-taraflı dönüşüm takibi; KVKK çerez onayı.','improvement',1,'2026-06-18 21:57:13',NULL,'2026-06-19 21:57:13','2026-06-19 21:57:13'),(7,'2026.6','Yeni Komuta Merkezi paneli','Animasyonlu KPI kartları, canlı grafikler ve tek-tab birleşik finans ekranı.','improvement',1,'2026-06-10 21:57:13',NULL,'2026-06-19 21:57:13','2026-06-19 21:57:13');
/*!40000 ALTER TABLE `app_updates` ENABLE KEYS */;
