INSERT INTO `email_templates` VALUES (1,'welcome','{site_name} ailesine hoş geldiniz','<p>Merhaba {name},</p><p>{site_name} hesabınız oluşturuldu. Şifrenizi belirlemek için: <a href=\"{reset_url}\">{reset_url}</a></p>','{site_name},{name},{reset_url}',1,NULL,'2026-06-15 21:41:33','2026-06-15 21:41:33'),(2,'password_reset','{site_name} — Şifre sıfırlama','<p>Merhaba {name},</p><p>Şifrenizi sıfırlamak için: <a href=\"{reset_url}\">{reset_url}</a></p><p>Bu isteği siz yapmadıysanız yok sayın.</p>','{site_name},{name},{reset_url}',1,NULL,'2026-06-15 21:41:33','2026-06-15 21:41:33'),(3,'subscription_ended','{site_name} — Aboneliğiniz sona erdi','<p>Merhaba {name},</p><p>{package} paketi aboneliğiniz {date} tarihinde sona erdi. Devam etmek için ödeme yapabilirsiniz.</p>','{site_name},{name},{package},{date}',1,NULL,'2026-06-15 21:41:33','2026-06-15 21:41:33'),(4,'trial_ending','{site_name} — Deneme süreniz bitiyor','<p>Merhaba {name},</p><p>Deneme süreniz {days} gün sonra ({date}) sona erecek. Kesintisiz devam için paketinizi etkinleştirin.</p>','{site_name},{name},{days},{date}',1,NULL,'2026-06-15 21:41:33','2026-06-15 21:41:33'),(5,'payment_confirmed','{site_name} — Ödemeniz onaylandı','<p>Merhaba {name},</p><p>{amount} tutarındaki ödemeniz onaylandı, aboneliğiniz aktif. Teşekkürler.</p>','{site_name},{name},{amount}',1,NULL,'2026-06-15 21:41:33','2026-06-15 21:41:33'),(6,'support_replied','{site_name} — Destek talebinize yanıt geldi','<p>Merhaba {name},</p><p>#{ticket} numaralı destek talebinize yanıt verildi. Görüntülemek için panele giriş yapın.</p>','{site_name},{name},{ticket}',1,NULL,'2026-06-15 21:41:33','2026-06-15 21:41:33');
/*!40000 ALTER TABLE `email_templates` ENABLE KEYS */;
UNLOCK TABLES;

