INSERT INTO `faqs` VALUES (1,'genel','Entegratör Yazılımı nedir?','Tüm pazaryerlerini (Trendyol, Hepsiburada, Amazon, n11 ve daha fazlası) tek panelden yöneten çok-kiracılı bir entegrasyon platformudur.',1,1,NULL,'2026-06-15 21:41:33','2026-06-21 13:34:35'),(2,'genel','Ücretsiz deneme var mı?','Evet. Paketlere bağlı olarak ücretsiz deneme süresi sunulur; deneme süresince tüm paket özelliklerini kullanabilirsiniz.',2,1,NULL,'2026-06-15 21:41:33','2026-06-15 21:41:33'),(3,'odeme','Ödeme nasıl yapılır?','Havale/EFT ile ödeme yapıp dekontunuzu panelden yükleyebilirsiniz; ödemeniz onaylandığında aboneliğiniz aktifleşir.',3,1,NULL,'2026-06-15 21:41:33','2026-06-15 21:41:33');
